add_action( 'rest_api_init', function () {
    register_rest_route( 'macrolingo/v1', '/tool-finder', array(
        'methods'             => 'POST',
        'permission_callback' => '__return_true',
        'callback'            => 'ml_tool_finder_recommend',
    ) );
} );

function ml_tool_finder_recommend( WP_REST_Request $req ) {
    $text = trim( (string) $req->get_param( 'request' ) );
    if ( $text === '' || mb_strlen( $text ) > 1500 ) {
        return new WP_Error( 'ml_tf_bad', 'Please describe the tool you need in under 1,500 characters.', array( 'status' => 400 ) );
    }
    // 15 searches per visitor per ten minutes: the recommender is paid for
    $ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? $_SERVER['REMOTE_ADDR'] : 'unknown';
    $key = 'ml_tf_' . md5( $ip );
    $n   = (int) get_transient( $key );
    if ( $n >= 15 ) {
        return new WP_Error( 'ml_tf_busy', 'Too many searches in a short time. Please try again in a few minutes.', array( 'status' => 429 ) );
    }
    set_transient( $key, $n + 1, 10 * MINUTE_IN_SECONDS );

    $lines = array();
    foreach ( ml_tool_finder_tools() as $t ) {
        $lines[] = '- ' . $t['name'] . ' | ' . $t['section'] . ' | ' . $t['brief'];
    }
    $message = "USER REQUEST: " . $text . "\n\nTOOL DATABASE:\n" . implode( "\n", $lines )
             . "\n\nRecommend 5-10 tools ranked by fit. Return ONLY JSON.";

    $res = wp_remote_post( 'https://macrolingo-tool-finder.vercel.app/api/recommend', array(
        'timeout' => 60,
        'headers' => array( 'Content-Type' => 'application/json' ),
        'body'    => wp_json_encode( array( 'userMessage' => $message ) ),
    ) );
    if ( is_wp_error( $res ) || wp_remote_retrieve_response_code( $res ) !== 200 ) {
        return new WP_Error( 'ml_tf_upstream', 'Something went wrong. Try rephrasing your description.', array( 'status' => 502 ) );
    }
    $body = json_decode( wp_remote_retrieve_body( $res ), true );
    $out  = '';
    if ( isset( $body['content'] ) && is_array( $body['content'] ) ) {
        foreach ( $body['content'] as $part ) {
            if ( isset( $part['type'], $part['text'] ) && $part['type'] === 'text' ) {
                $out .= $part['text'];
            }
        }
    }
    return rest_ensure_response( array( 'text' => trim( $out ) ) );
}

