    <button type="button" class="ml-tf-new" hidden>&larr; New search</button>
  </div>
  <div class="ml-tf-body" aria-live="polite"></div>
  <p class="ml-tf-foot">Tools listed here don&rsquo;t imply endorsement. You use them at your own risk. We encourage you to explore and experiment.</p>
</div>
<script>
window.ML_TOOLS = <?php echo wp_json_encode( ml_tool_finder_tools() ); ?>;
(function () {
  var root = document.getElementById('ml-tf');
  if (!root || root.__ml) { return; }
  root.__ml = true;
  var TOOLS = window.ML_TOOLS || [];
  var API = root.getAttribute('data-api');
  var CONTACT = root.getAttribute('data-contact');
  var body = root.querySelector('.ml-tf-body');
  var newBtn = root.querySelector('.ml-tf-new');
  var countEl = root.querySelector('.ml-tf-count');
  var KEY = 'ml-saved-tools';

  var unique = TOOLS.filter(function (t, i, a) { return a.findIndex(function (o) { return o.name === t.name; }) === i; });
  var CATS = TOOLS.map(function (t) { return t.section; }).filter(function (s, i, a) { return a.indexOf(s) === i; }).sort();

  var state = { tab: 'search', query: '', results: null, label: 'You searched for:', busy: false, error: '', unclear: false, open: null };
  var saved = {};
  try { saved = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch (e) { saved = {}; }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text != null) { n.textContent = text; }
    return n;
  }
  function savedCount() { return Object.keys(saved).length; }
  function toggleSave(name) {
    if (saved[name]) { delete saved[name]; } else { saved[name] = true; }
    try { localStorage.setItem(KEY, JSON.stringify(saved)); } catch (e) {}
    render();
  }

  function toolLink(t, cls) {
    var a = el('a', cls);
    a.href = t.href; a.target = '_blank'; a.rel = 'noopener noreferrer';
    a.appendChild(document.createTextNode(t.name));
    a.appendChild(el('span', 'ml-tf-ext', ' ↗'));
    return a;
  }
  function starButton(t, withLabel) {
    var on = !!saved[t.name];
    var b = el('button', 'ml-tf-star' + (on ? ' is-on' : ''), withLabel ? (on ? '★ Saved' : '☆ Save') : (on ? '★' : '☆'));
    b.type = 'button';
    b.setAttribute('aria-pressed', on ? 'true' : 'false');
    b.title = on ? 'Remove from saved' : 'Save this tool';
    b.addEventListener('click', function () { toggleSave(t.name); });
    return b;
  }

  // a result: name, category, why it fits, save and see similar
  function resultCard(t, i) {
    var c = el('article', 'ml-tf-result');
    c.style.animationDelay = (i * 0.06) + 's';
    var top = el('div', 'ml-tf-result-top');
    top.appendChild(toolLink(t, 'ml-tf-result-name'));
    top.appendChild(el('span', 'ml-tf-pill', t.section));
    c.appendChild(top);
    c.appendChild(el('p', 'ml-tf-reason', t.reason || t.brief));
    var act = el('div', 'ml-tf-actions');
    act.appendChild(starButton(t, true));
    var sim = el('button', 'ml-tf-similar', 'See similar →');
    sim.type = 'button';
    sim.addEventListener('click', function () { similar(t.section); });
    act.appendChild(sim);
    c.appendChild(act);
    return c;
  }
  // a compact card, in a category and in Saved
  function toolCard(t) {
    var c = el('div', 'ml-tf-tool');
    var words = el('div', 'ml-tf-tool-words');
    words.appendChild(toolLink(t, 'ml-tf-tool-name'));
    words.appendChild(el('p', 'ml-tf-tool-brief', t.brief));
    c.appendChild(words);
    c.appendChild(starButton(t, false));
    return c;
  }

  function suggestBox() {
    var b = el('div', 'ml-tf-note');
    var w = el('div');
    w.appendChild(el('p', 'ml-tf-note-head', 'Know a tool we’re missing?'));
    w.appendChild(el('p', 'ml-tf-note-text', 'Help us cover more ground.'));
    b.appendChild(w);
    var a = el('a', 'ml-tf-btn ml-tf-btn-soft', 'Suggest a tool');
    a.href = CONTACT;
    b.appendChild(a);
    return b;
  }
  function expertBox() {
    var b = el('div', 'ml-tf-note ml-tf-note-accent');
    var w = el('div');
    w.appendChild(el('p', 'ml-tf-note-head', 'Still not sure which tool fits your workflow?'));
    w.appendChild(el('p', 'ml-tf-note-text', 'Our team works with journals and researchers across every discipline.'));
    b.appendChild(w);
    var a = el('a', 'ml-tf-btn', 'Talk to an expert');
    a.href = CONTACT;
    b.appendChild(a);
    return b;
  }

  function similar(section) {
    state.results = TOOLS.filter(function (t) { return t.section === section; }).slice(0, 8)
      .map(function (t) { return Object.assign({}, t, { reason: t.brief }); });
    state.label = 'Similar tools in:';
    state.query = section;
    state.tab = 'search';
    render();
    root.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function reset() {
    state.query = ''; state.results = null; state.error = ''; state.unclear = false; state.label = 'You searched for:';
    render();
    setTimeout(function () { var t = root.querySelector('textarea'); if (t) { t.focus(); } }, 50);
  }

  function search() {
    var q = state.query.trim();
    if (!q || state.busy) { return; }
    state.busy = true; state.error = ''; state.results = null; state.unclear = false;
    render();
    fetch(API, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ request: q }) })
      .then(function (r) { return r.json().then(function (d) { return { ok: r.ok, d: d }; }); })
      .then(function (res) {
        if (!res.ok) { throw new Error((res.d && res.d.message) || 'Something went wrong. Try rephrasing your description.'); }
        var parsed = JSON.parse(String(res.d.text || '').replace(/```json|```/g, '').trim());
        if (parsed.unclear) { state.unclear = true; return; }
        if (parsed.searchLabel) { state.label = parsed.searchLabel; }
        state.results = (parsed.recommendations || []).map(function (k) {
          var hit = TOOLS.find(function (t) { return t.name.toLowerCase() === String(k.name).toLowerCase(); });
          return hit ? Object.assign({}, hit, { reason: k.reason }) : null;
        }).filter(Boolean);
      })
      .catch(function (e) { state.error = (e && e.message && e.message.indexOf('JSON') < 0) ? e.message : 'Something went wrong. Try rephrasing your description.'; })
      .then(function () { state.busy = false; render(); });
  }

  function viewSearch() {
    var v = el('div', 'ml-tf-view');
    if (state.results) {
      var sum = el('p', 'ml-tf-summary');
      sum.appendChild(el('span', 'ml-tf-summary-label', state.label + ' '));
      sum.appendChild(el('em', 'ml-tf-summary-query', '“' + state.query + '”'));
      sum.appendChild(el('span', 'ml-tf-summary-count', ' — ' + state.results.length + ' matches'));
      v.appendChild(sum);
      if (state.results.length) {
        var list = el('div', 'ml-tf-results');
        state.results.forEach(function (t, i) { list.appendChild(resultCard(t, i)); });
        v.appendChild(list);
      } else {
        v.appendChild(el('p', 'ml-tf-empty', 'No strong matches found. Try rephrasing or broadening your request.'));
      }
      var again = el('button', 'ml-tf-btn ml-tf-btn-soft ml-tf-again', '← Search again');
      again.type = 'button';
      again.addEventListener('click', reset);
      v.appendChild(again);
      v.appendChild(expertBox());
      v.appendChild(suggestBox());
      return v;
    }
    v.appendChild(el('h2', 'ml-tf-title', 'Find the AI tools you need'));
    v.appendChild(el('p', 'ml-tf-lead', 'Describe what you need. Be as specific as possible. We’ll serve up 5 to 10 options for you to try.'));
    v.appendChild(el('p', 'ml-tf-meta', '*Type in any language. · ' + unique.length + '+ tools across ' + CATS.length + ' categories'));
    var label = el('label', 'ml-tf-sr', 'Describe the tool you need');
    label.setAttribute('for', 'ml-tf-query');
    v.appendChild(label);
    var ta = el('textarea', 'ml-tf-input');
    ta.id = 'ml-tf-query';
    ta.rows = 4;
    ta.placeholder = 'e.g., I need to find peer reviewers for an interdisciplinary paper crossing marine biology and materials science...';
    ta.value = state.query;
    ta.addEventListener('input', function () { state.query = ta.value; go.disabled = state.busy || !ta.value.trim(); });
    ta.addEventListener('keydown', function (e) { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { search(); } });
    v.appendChild(ta);
    var row = el('div', 'ml-tf-row');
    row.appendChild(el('span', 'ml-tf-hint', 'Ctrl+Enter to search'));
    var go = el('button', 'ml-tf-btn', state.busy ? 'Searching...' : 'Find tools');
    go.type = 'button';
    go.disabled = state.busy || !state.query.trim();
    go.addEventListener('click', search);
    row.appendChild(go);
    v.appendChild(row);
    if (state.busy) {
      var wait = el('div', 'ml-tf-wait');
      var dots = el('span', 'ml-tf-dots');
      dots.appendChild(el('i')); dots.appendChild(el('i')); dots.appendChild(el('i'));
      wait.appendChild(dots);
      wait.appendChild(el('span', null, 'Matching your request against the database...'));
      v.appendChild(wait);
    }
    if (state.error) { v.appendChild(el('p', 'ml-tf-alert', state.error)); }
    if (state.unclear) {
      v.appendChild(el('p', 'ml-tf-alert ml-tf-alert-soft', 'We couldn’t understand that request. Please describe, in plain language, the kind of scholarly tool you’re looking for — for example: “I need a tool to check manuscripts for plagiarism” or “I’m looking for something that helps me find peer reviewers.”'));
    }
    v.appendChild(suggestBox());
    return v;
  }

  function viewBrowse() {
    var v = el('div', 'ml-tf-view');
    v.appendChild(el('h2', 'ml-tf-title', 'Browse by category'));
    v.appendChild(el('p', 'ml-tf-meta', unique.length + ' tools across ' + CATS.length + ' categories'));
    var grid = el('div', 'ml-tf-cats');
    CATS.forEach(function (cat) {
      var tools = TOOLS.filter(function (t) { return t.section === cat; })
        .filter(function (t, i, a) { return a.findIndex(function (o) { return o.name === t.name; }) === i; });
      var open = state.open === cat;
      var wrap = el('div', 'ml-tf-cat' + (open ? ' is-open' : ''));
      var b = el('button', 'ml-tf-cat-btn');
      b.type = 'button';
      b.setAttribute('aria-expanded', open ? 'true' : 'false');
      b.appendChild(el('span', 'ml-tf-cat-name', cat));
      var side = el('span', 'ml-tf-cat-side');
      side.appendChild(el('span', 'ml-tf-cat-n', String(tools.length)));
      side.appendChild(el('span', 'ml-tf-cat-arrow', '›'));
      b.appendChild(side);
      b.addEventListener('click', function () { state.open = open ? null : cat; render(); });
      wrap.appendChild(b);
      if (open) {
        var list = el('div', 'ml-tf-cat-list');
        tools.forEach(function (t) { list.appendChild(toolCard(t)); });
        wrap.appendChild(list);
      }
      grid.appendChild(wrap);
    });
    v.appendChild(grid);
    v.appendChild(suggestBox());
    return v;
  }

  function viewSaved() {
    var v = el('div', 'ml-tf-view');
    v.appendChild(el('h2', 'ml-tf-title', 'Your saved tools'));
    var n = savedCount();
    if (!n) {
      var e = el('div', 'ml-tf-none');
      e.appendChild(el('div', 'ml-tf-none-star', '☆'));
      e.appendChild(el('p', null, 'You haven’t saved any tools yet.'));
      e.appendChild(el('p', 'ml-tf-hint', 'Use the ☆ button on any tool card to save it here for later.'));
      var s = el('button', 'ml-tf-btn', 'Start searching');
      s.type = 'button';
      s.addEventListener('click', function () { state.tab = 'search'; render(); });
      e.appendChild(s);
      v.appendChild(e);
      return v;
    }
    v.appendChild(el('p', 'ml-tf-meta', n + ' tool' + (n !== 1 ? 's' : '') + ' saved'));
    var list = el('div', 'ml-tf-cat-list ml-tf-saved');
    unique.filter(function (t) { return saved[t.name]; }).forEach(function (t) { list.appendChild(toolCard(t)); });
    v.appendChild(list);
    return v;
  }

  function render() {
    root.querySelectorAll('.ml-tf-tab').forEach(function (t) {
      var on = t.getAttribute('data-tab') === state.tab;
      t.classList.toggle('is-on', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    var n = savedCount();
    countEl.textContent = n ? ' (' + n + ')' : '';
    newBtn.hidden = !(state.tab === 'search' && state.results);
    body.innerHTML = '';
    body.appendChild(state.tab === 'browse' ? viewBrowse() : state.tab === 'saved' ? viewSaved() : viewSearch());
  }

  root.querySelectorAll('.ml-tf-tab').forEach(function (t) {
    t.addEventListener('click', function () { state.tab = t.getAttribute('data-tab'); state.results = null; render(); });
  });
  newBtn.addEventListener('click', reset);
  render();
})();
</script>
    <?php
    return ob_get_clean();
} );
